-- Base Normativa EletricAI (2026-11-16).
--
-- A IA faz RAG em normative_chunks antes de gerar projetos, mas a tabela
-- estava VAZIA, e a busca removia acentos das palavras do pedido mas
-- comparava com o texto acentuado ("tensao" nunca casava com "tensão").
--
-- 1. Coluna gerada search_text: minúsculas e sem acento (translate/lower são
--    IMMUTABLE), consultada pelo servidor.
-- 2. Conteúdo: RESUMOS TÉCNICOS PRÓPRIOS (não reproduzem texto das normas,
--    protegido por direito autoral), com a seção de referência. Idempotente:
--    só insere documento/trechos ausentes.

ALTER TABLE public.normative_chunks
  ADD COLUMN IF NOT EXISTS search_text text
  GENERATED ALWAYS AS (
    lower(translate(chunk_text,
      'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ',
      'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn'))
  ) STORED;

CREATE INDEX IF NOT EXISTS idx_normative_chunks_category ON public.normative_chunks (category);

INSERT INTO public.normative_documents (code, title, section, source_type, version)
SELECT v.code, v.title, v.section, 'resumo_tecnico_eletricai', '2026-11'
FROM (VALUES
  ($nb$ELETRICAI-NBR5410$nb$, $nb$Instalações elétricas de baixa tensão — resumo técnico$nb$, $nb$ABNT NBR 5410:2004$nb$),
  ($nb$ELETRICAI-NBR14039$nb$, $nb$Instalações elétricas de média tensão — resumo técnico$nb$, $nb$ABNT NBR 14039:2021$nb$),
  ($nb$ELETRICAI-NR10$nb$, $nb$Segurança em instalações e serviços em eletricidade — resumo técnico$nb$, $nb$NR-10$nb$),
  ($nb$ELETRICAI-NR12$nb$, $nb$Segurança no trabalho em máquinas e equipamentos — resumo técnico$nb$, $nb$NR-12$nb$),
  ($nb$ELETRICAI-MAQUINAS$nb$, $nb$Segurança de máquinas e categorias de parada — resumo técnico$nb$, $nb$IEC 60204-1 / ABNT NBR ISO 13849-1$nb$),
  ($nb$ELETRICAI-MANOBRA$nb$, $nb$Dispositivos de manobra e proteção — resumo técnico$nb$, $nb$IEC 60947 / IEC 60898-1$nb$),
  ($nb$ELETRICAI-CURTO$nb$, $nb$Correntes de curto-circuito — resumo técnico$nb$, $nb$IEC 60909-0$nb$),
  ($nb$ELETRICAI-MOTORES$nb$, $nb$Acionamento de motores de indução — resumo técnico$nb$, $nb$Prática de engenharia / IEC 60034$nb$),
  ($nb$ELETRICAI-QEE$nb$, $nb$Qualidade de energia e fator de potência — resumo técnico$nb$, $nb$IEEE 519-2014 / ANEEL$nb$),
  ($nb$ELETRICAI-AUTOMACAO$nb$, $nb$Alarmes, IHM e programação de CLP — resumo técnico$nb$, $nb$ISA-18.2 / ISA-101 / IEC 61131-3$nb$),
  ($nb$ELETRICAI-IDENT$nb$, $nb$Identificação de equipamentos e documentação — resumo técnico$nb$, $nb$IEC 81346-2 / IEC 60947-5-1$nb$)
) AS v(code, title, section)
WHERE NOT EXISTS (SELECT 1 FROM public.normative_documents d WHERE d.code = v.code);

INSERT INTO public.normative_chunks (document_id, category, chunk_text, metadata)
SELECT d.id, v.category, v.chunk_text, jsonb_build_object('origem', 'resumo_tecnico_eletricai')
FROM (VALUES
  ($nb$ELETRICAI-NBR5410$nb$, $nb$dimensionamento$nb$, $nb$NBR 5410 6.2.6.1 (Tabela 47) — seção mínima dos condutores de cobre: circuitos de iluminação 1,5 mm²; circuitos de força, incluindo tomadas de uso geral, 2,5 mm²; circuitos de sinalização e comando 0,5 mm². A seção final é a maior entre o critério de seção mínima, a capacidade de condução corrigida, a queda de tensão e a proteção contra curto-circuito.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$queda_de_tensao$nb$, $nb$NBR 5410 6.2.7 — queda de tensão máxima, em relação à tensão nominal, calculada a partir da origem da instalação: 7% quando a instalação é alimentada por transformador ou subestação própria (ou gerador próprio); 4% quando alimentada diretamente pela rede pública de baixa tensão, a partir do ponto de entrega. Os circuitos terminais não devem ultrapassar 4%. Durante a partida de motores admite-se queda maior nos terminais do dispositivo de partida, limitada a 10% da tensão nominal.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$dimensionamento$nb$, $nb$NBR 5410 6.2.5 — capacidade de condução de corrente: o valor tabelado (Tabelas 36 a 39, conforme método de instalação, isolação e número de condutores carregados) deve ser multiplicado pelos fatores de correção de temperatura ambiente (Tabela 40) e de agrupamento de circuitos (Tabelas 42 a 45). A corrente de projeto Ib nunca pode superar a capacidade corrigida Iz.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$protecao$nb$, $nb$NBR 5410 — coordenação entre condutor e proteção contra sobrecarga: Ib ≤ In ≤ Iz e I2 ≤ 1,45 × Iz, onde Ib é a corrente de projeto, In a corrente nominal do dispositivo de proteção, Iz a capacidade de condução corrigida e I2 a corrente que assegura a atuação do dispositivo. Disjuntores conforme IEC 60898/60947-2 atendem à segunda condição quando a primeira é satisfeita.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$aterramento$nb$, $nb$NBR 5410 6.4.3 (Tabela 58) — seção mínima do condutor de proteção PE, de mesmo material da fase: fase S ≤ 16 mm² → PE = S; 16 < S ≤ 35 mm² → PE = 16 mm²; S > 35 mm² → PE = S/2. Todo equipamento classe I (massa metálica acessível), como motores e tomadas, deve ter PE ligado ao barramento de equipotencialização.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$dimensionamento$nb$, $nb$NBR 5410 6.2.6.2 — condutor neutro: em circuitos monofásicos e em circuitos com conteúdo harmônico relevante o neutro tem a mesma seção da fase. Em circuitos trifásicos equilibrados com fase acima de 25 mm² (cobre) e taxa de terceira harmônica até 15%, o neutro pode ser reduzido conforme a Tabela 48. Com terceira harmônica acima de 33%, a corrente de neutro pode superar a de fase e o neutro deve ser dimensionado por ela.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$protecao$nb$, $nb$NBR 5410 5.1.3.2.2 — uso obrigatório de dispositivo DR de alta sensibilidade (IΔn ≤ 30 mA) em: circuitos de locais com banheira ou chuveiro; tomadas em áreas externas; tomadas de cozinhas, copas, lavanderias, áreas de serviço, garagens e demais áreas internas molhadas ou sujeitas a lavagem; circuitos que alimentem equipamentos em áreas externas.$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$aterramento$nb$, $nb$NBR 5410 — esquemas de aterramento: TN-S (neutro e PE separados), TN-C (PEN combinado; proibido DR e proibido seccionar o PEN), TN-C-S, TT (massas aterradas em eletrodo próprio; o seccionamento automático exige DR, com RA × IΔn ≤ 50 V em locais secos) e IT (neutro isolado ou aterrado por impedância; exige dispositivo supervisor de isolamento).$nb$),
  ($nb$ELETRICAI-NBR5410$nb$, $nb$protecao$nb$, $nb$NBR 5410 6.3.5 — dispositivos de proteção contra surtos (DPS): na origem da instalação (quadro de entrada) usa-se DPS classe I quando há risco de descarga direta (SPDA) ou classe II nos demais casos; DPS adicionais classe II/III próximos a equipamentos sensíveis. A coordenação entre estágios depende do comprimento do cabo entre eles.$nb$),
  ($nb$ELETRICAI-NBR14039$nb$, $nb$media_tensao$nb$, $nb$NBR 14039 — aplica-se a instalações de 1,0 kV a 36,2 kV. A subestação de entrada exige proteção geral em média tensão: por disjuntor acionado por relé secundário com funções de sobrecorrente de fase e neutro (50/51 e 50N/51N) ou, dentro dos limites da concessionária, por chave seccionadora com fusíveis. Barramentos, transformadores e massas devem ser interligados à malha de aterramento.$nb$),
  ($nb$ELETRICAI-NR10$nb$, $nb$seguranca$nb$, $nb$NR-10 — faixas de tensão: extra-baixa tensão até 50 V CA ou 120 V CC; baixa tensão acima disso até 1000 V CA ou 1500 V CC; alta tensão acima de 1000 V CA ou 1500 V CC. Estabelecimentos com carga instalada acima de 75 kW devem manter o Prontuário de Instalações Elétricas, com diagramas unifilares atualizados, procedimentos e laudos do SPDA e de aterramento.$nb$),
  ($nb$ELETRICAI-NR10$nb$, $nb$seguranca$nb$, $nb$NR-10 — instalação desenergizada só é liberada para trabalho após, nesta ordem: seccionamento; impedimento de reenergização (bloqueio e etiquetagem); constatação da ausência de tensão; instalação de aterramento temporário com equipotencialização dos condutores; proteção dos elementos energizados existentes na zona controlada; instalação da sinalização de impedimento de reenergização. Só trabalhadores qualificados, habilitados ou capacitados e autorizados podem intervir.$nb$),
  ($nb$ELETRICAI-NR12$nb$, $nb$seguranca$nb$, $nb$NR-12 — dispositivos de parada de emergência: devem ser acessíveis e visíveis, ter prioridade sobre os demais comandos, provocar a parada da máquina o mais rapidamente possível sem criar risco adicional, e o rearme deve ser manual e intencional, sem religar a máquina automaticamente. A parada de emergência não substitui as proteções fixas e móveis, e os circuitos de segurança são escolhidos por análise de risco conforme ABNT NBR ISO 13849-1.$nb$),
  ($nb$ELETRICAI-MAQUINAS$nb$, $nb$seguranca$nb$, $nb$IEC 60204-1 — categorias de parada: categoria 0, remoção imediata da energia dos atuadores (parada não controlada); categoria 1, parada controlada com energia disponível e remoção da energia ao final; categoria 2, parada controlada mantendo a energia. A função de parada de emergência deve ser categoria 0 ou 1, realizada por dispositivos eletromecânicos com contatos NF de abertura positiva, independentemente da lógica do CLP.$nb$),
  ($nb$ELETRICAI-MAQUINAS$nb$, $nb$seguranca$nb$, $nb$ABNT NBR ISO 13849-1 — desempenho de partes de sistemas de comando relacionadas à segurança: nível de performance PL de a (menor) a e (maior), determinado pela arquitetura (categorias B, 1, 2, 3 e 4), pela confiabilidade dos componentes (MTTFd), pela cobertura de diagnóstico (DC) e por falhas de causa comum. A categoria 3 exige que uma falha única não leve à perda da função de segurança; a 4, também detecção da falha.$nb$),
  ($nb$ELETRICAI-MANOBRA$nb$, $nb$protecao$nb$, $nb$IEC 60947-4-1 — categorias de utilização de contatores: AC-1 cargas não indutivas ou pouco indutivas; AC-3 motores de gaiola com partida e desligamento em regime (corrente de interrupção igual à nominal do motor); AC-4 motores de gaiola com partida, inversão e manobras por impulsos (jogging). Um contator deve ser escolhido pela corrente nominal na categoria de uso real, não apenas pela corrente térmica AC-1.$nb$),
  ($nb$ELETRICAI-MANOBRA$nb$, $nb$protecao$nb$, $nb$IEC 60947-4-1 — classes de disparo dos relés de sobrecarga, tempo máximo de atuação a 7,2 × Ir partindo do estado frio: classe 10A, de 2 a 10 s; classe 10, de 4 a 10 s; classe 20, de 6 a 20 s; classe 30, de 9 a 30 s. Partidas longas (cargas de alta inércia) pedem classe 20 ou 30 para não disparar durante a aceleração. O relé deve ser ajustado na corrente nominal do motor.$nb$),
  ($nb$ELETRICAI-MANOBRA$nb$, $nb$protecao$nb$, $nb$IEC 60898-1 — curvas de disparo magnético de minidisjuntores: curva B entre 3 e 5 × In (cargas resistivas, cabos longos); curva C entre 5 e 10 × In (uso geral, iluminação e cargas mistas); curva D entre 10 e 20 × In (cargas com alta corrente de partida, transformadores e motores). A capacidade de interrupção (Icn/Icu) deve ser maior ou igual à corrente de curto-circuito presumida no ponto de instalação.$nb$),
  ($nb$ELETRICAI-CURTO$nb$, $nb$curto_circuito$nb$, $nb$IEC 60909-0 — corrente de curto-circuito trifásica inicial I"k = c × Un / (√3 × Zk), com fator de tensão c (em baixa tensão, cmax = 1,05 para tolerância de tensão de 6% e 1,10 para 10%; em média tensão, 1,10). A corrente de pico é ip = κ × √2 × I"k, com κ entre 1,0 e 2,0 conforme a relação R/X da impedância. O esforço térmico e a capacidade de interrupção dos dispositivos são verificados contra esses valores.$nb$),
  ($nb$ELETRICAI-MOTORES$nb$, $nb$motores$nb$, $nb$Partida de motores de indução de gaiola: partida direta (DOL) solicita de 6 a 8 × In e conjugado pleno; estrela-triângulo reduz corrente e conjugado de partida a cerca de 1/3 dos valores da partida direta e exige motor com seis terminais acessíveis; soft-starter controla a tensão e reduz a corrente, com perda de conjugado; inversor de frequência permite partida com cerca de 1 a 1,5 × In e conjugado nominal, controlando a velocidade.$nb$),
  ($nb$ELETRICAI-MOTORES$nb$, $nb$motores$nb$, $nb$Corrente nominal de motor trifásico: In = P / (√3 × U × η × cos φ), com P a potência mecânica no eixo em watts, U a tensão de linha, η o rendimento e cos φ o fator de potência, ambos da placa ou catálogo. O circuito do motor é dimensionado com fator de serviço e o condutor deve suportar 1,25 × In quando alimenta um único motor em regime contínuo.$nb$),
  ($nb$ELETRICAI-QEE$nb$, $nb$qualidade_energia$nb$, $nb$Fator de potência: a regulação brasileira (ANEEL) adota 0,92 como valor de referência; consumo de energia reativa abaixo desse valor é faturado como excedente. A correção usa bancos de capacitores, cuja potência reativa é Qc = P × (tg φ1 − tg φ2). Em instalações com harmônicas relevantes os capacitores devem ser dessintonizados (com reatores) para evitar ressonância.$nb$),
  ($nb$ELETRICAI-QEE$nb$, $nb$qualidade_energia$nb$, $nb$IEEE 519-2014 — distorção harmônica de tensão no ponto de acoplamento comum: para barramentos até 1 kV, distorção harmônica total (THD) até 8% e harmônica individual até 5%. Os limites de distorção de corrente (TDD) dependem da relação Isc/IL no ponto de acoplamento. Inversores, retificadores e fontes chaveadas são as principais fontes de terceira, quinta e sétima harmônicas.$nb$),
  ($nb$ELETRICAI-AUTOMACAO$nb$, $nb$alarmes$nb$, $nb$ISA-18.2 — gestão de alarmes: todo alarme deve exigir uma ação definida do operador; estados do ciclo de vida: normal, ativo não reconhecido, ativo reconhecido, retornado não reconhecido, além de suprimido, fora de serviço e engavetado (shelved). Como referência de carga, busca-se da ordem de um alarme a cada 10 minutos por operador em operação normal; inundações de alarmes devem ser tratadas por racionalização e supressão por estado.$nb$),
  ($nb$ELETRICAI-AUTOMACAO$nb$, $nb$ihm$nb$, $nb$ISA-101 — IHM de alto desempenho: fundo neutro (cinza), equipamentos em tons discretos e cor saturada reservada para condições anormais e alarmes, de modo que o desvio chame a atenção imediatamente. Telas hierárquicas: visão geral da planta, área, unidade e detalhe. Valores numéricos acompanhados de unidade e, quando possível, de faixa de operação normal.$nb$),
  ($nb$ELETRICAI-AUTOMACAO$nb$, $nb$clp$nb$, $nb$IEC 61131-3 — linguagens de programação de CLP: Ladder (LD), diagrama de blocos de função (FBD), texto estruturado (ST), sequenciamento gráfico (SFC) e lista de instruções (IL, declarada obsoleta na 3ª edição). Unidades de organização de programa (POU): programa, bloco de função (com memória de instância) e função (sem memória). Temporizadores normalizados: TON, TOF e TP; contadores: CTU, CTD e CTUD.$nb$),
  ($nb$ELETRICAI-IDENT$nb$, $nb$documentacao$nb$, $nb$IEC 81346 — identificação de equipamentos por aspectos: = função (planta/sistema), + localização (painel/sala) e - produto (equipamento), por exemplo =ETE+QGBT-K3. A IEC 81346-2 define as letras de classe pela finalidade: Q para comutação de potência, F para proteção, M para motores, T para conversão de energia, B para sensores, S para comando manual, X para bornes e conexões, P para apresentação de informação. Na prática brasileira também é comum K/KM para contatores.$nb$),
  ($nb$ELETRICAI-IDENT$nb$, $nb$documentacao$nb$, $nb$IEC 60947-5-1 — numeração de terminais: bobina A1-A2; contatos principais 1-2, 3-4, 5-6 (entrada L1/L2/L3, saída T1/T2/T3); contatos auxiliares com dígito de sequência e dígito de função, NA terminando em 3-4 (13-14, 23-24) e NF em 1-2 (21-22, 31-32); relé de sobrecarga com NF 95-96 e NA 97-98. A referência cruzada da documentação associa cada contato usado à bobina que o comanda.$nb$)
) AS v(code, category, chunk_text)
JOIN public.normative_documents d ON d.code = v.code
WHERE NOT EXISTS (SELECT 1 FROM public.normative_chunks c WHERE c.chunk_text = v.chunk_text);
